// =====================================================================
//  KC Spa — Artefacto conectado a TU Supabase (vía API REST + Auth con fetch)
//  ---------------------------------------------------------------------
//  No usa la librería @supabase/supabase-js (no está disponible en artefactos);
//  habla directo con la API REST de Supabase, que hace exactamente lo mismo.
//  1) Al abrir, pega tu Project URL y anon key (Supabase → Project Settings → API).
//  2) Inicia sesión con un usuario creado en Authentication que tenga su fila
//     en la tabla "usuarios" (mismo id).
//  Módulos activos: Pacientes, Maestros, Inventario, Agenda. El resto vienen luego.
//  Cuando lo lleves a tu repo (Vite), reemplaza este acceso REST por
//  @supabase/supabase-js y las llaves por variables VITE_*.
// =====================================================================

// ---------- Cliente REST mínimo sobre fetch ----------
function crearApi(url, anonKey, getToken) {
  const rest = `${url.replace(/\/$/, "")}/rest/v1`;
  const h = () => ({
    apikey: anonKey,
    Authorization: `Bearer ${getToken() || anonKey}`,
    "Content-Type": "application/json",
  });
  const ok = async (res) => {
    if (!res.ok) { let t; try { t = (await res.json()).message; } catch { t = await res.text(); } throw new Error(t || `Error ${res.status}`); }
    const txt = await res.text(); return txt ? JSON.parse(txt) : null;
  };
  return {
    select: (table, query = "") => fetch(`${rest}/${table}?${query}`, { headers: h() }).then(ok),
    insert: async (table, row) => { const r = await fetch(`${rest}/${table}`, { method: "POST", headers: { ...h(), Prefer: "return=representation" }, body: JSON.stringify(row) }).then(ok); return Array.isArray(r) ? r[0] : r; },
    update: (table, query, patch) => fetch(`${rest}/${table}?${query}`, { method: "PATCH", headers: { ...h(), Prefer: "return=representation" }, body: JSON.stringify(patch) }).then(ok),
    remove: (table, query) => fetch(`${rest}/${table}?${query}`, { method: "DELETE", headers: h() }).then(ok),
  };
}
async function authLogin(url, anonKey, email, password) {
  const res = await fetch(`${url.replace(/\/$/, "")}/auth/v1/token?grant_type=password`, {
    method: "POST", headers: { apikey: anonKey, "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "Correo o contraseña incorrectos.");
  return data; // { access_token, user, ... }
}
async function authUpdatePassword(url, anonKey, token, password) {
  const res = await fetch(`${url.replace(/\/$/, "")}/auth/v1/user`, {
    method: "PUT", headers: { apikey: anonKey, Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
    body: JSON.stringify({ password }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "No se pudo cambiar la contraseña.");
  return data;
}

