// =====================================================================
//  Shell
// =====================================================================
function Shell({ api, profile, locales, localActivo, setLocalActivo, onLogout }) {
  const rol = profile.rol; const P = PERMISOS[rol] || {};
  const [tab, setTab] = useState("agenda");
  const [menuOpen, setMenuOpen] = useState(false);
  const localNombre = locales.find((l) => l.id === localActivo)?.nombre ?? "";

  const NAV = [{ key: "dashboard", icon: Calendar, label: "Resumen" }];
  if (P.pacientes) NAV.push({ key: "pacientes", icon: Users, label: "Pacientes" });
  if (P.agenda) NAV.push({ key: "agenda", icon: Calendar, label: "Agenda" });
  NAV.push({ key: "atencion", icon: Stethoscope, label: "Atención" });
  if (P.inventario) NAV.push({ key: "caja", icon: Wallet, label: "Caja" });
  if (P.inventario) NAV.push({ key: "inventario", icon: Package, label: "Inventario" });
  if (P.maestros) NAV.push({ key: "balances", icon: TrendingUp, label: "Balances" });
  if (P.maestros) NAV.push({ key: "maestros", icon: FileText, label: "Maestros" });
  if (P.usuarios) NAV.push({ key: "usuarios", icon: Users, label: "Usuarios" });

  const irA = (k) => { setTab(k); setMenuOpen(false); };
  const NavBtn = ({ item }) => (
    <button onClick={() => irA(item.key)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left ${tab === item.key ? "bg-white text-gray-900" : "text-gray-200 hover:bg-white/10"}`}>
      <item.icon size={18} strokeWidth={1.8} /><span className="text-[15px]" style={{ fontFamily: "'Sora', sans-serif" }}>{item.label}</span>
    </button>
  );
  const SelectorLocal = () => locales.length > 1 ? (
    <div className="px-2 mb-3">
      <div className="flex items-center gap-1.5 text-[11px] mb-1" style={{ color: "#A9B9AA" }}><Store size={12} /> Local activo</div>
      <select value={localActivo} onChange={(e) => setLocalActivo(e.target.value)} className="w-full px-3 py-2 rounded-lg text-sm bg-white/10 text-white border border-white/20">
        {locales.map((l) => <option key={l.id} value={l.id} style={{ color: "#2E2E2E" }}>{l.nombre}</option>)}
      </select>
    </div>
  ) : null;

  const contenido = () => {
    if (tab === "pacientes" && P.pacientes) return <Pacientes api={api} P={P} localId={localActivo} usuarioId={profile.id} />;
    if (tab === "agenda" && P.agenda) return <Agenda api={api} localId={localActivo} usuarioId={profile.id} />;
    if (tab === "maestros" && P.maestros) return <Maestros api={api} localId={localActivo} />;
    if (tab === "inventario" && P.inventario) return <Inventario api={api} P={P} localId={localActivo} />;
    if (tab === "usuarios" && P.usuarios) return <Usuarios api={api} profile={profile} locales={locales} />;
    return <Proximamente titulo={NAV.find((n) => n.key === tab)?.label ?? "Módulo"} />;
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row" style={{ background: "#FBF9F3" }}>
      <style>{FONTS}</style>
      <div className="md:hidden flex items-center justify-between px-4 py-3 sticky top-0 z-30" style={{ background: "#2E2E2E" }}>
        <span className="text-white text-[16px]" style={{ fontFamily: "'Fraunces', serif" }}>KC Spa</span>
        <button onClick={() => setMenuOpen((v) => !v)} className="text-white">{menuOpen ? <X size={22} /> : <Menu size={22} />}</button>
      </div>
      {menuOpen && (
        <div className="md:hidden flex flex-col gap-1 p-4 z-20" style={{ background: "#2E2E2E" }}>
          <div className="px-4 pb-3 mb-1 border-b border-white/10"><div className="text-white text-sm">{profile.nombre}</div><div className="text-gray-300 text-xs">{ROLES[rol]} · 📍 {localNombre}</div></div>
          <SelectorLocal />
          {NAV.map((it) => <NavBtn key={it.key} item={it} />)}
          <button onClick={onLogout} className="text-left px-4 py-3 rounded-xl hover:bg-white/10 text-[15px]" style={{ color: "#E3A48E" }}>Cerrar sesión</button>
        </div>
      )}
      <aside className="hidden md:flex w-64 shrink-0 flex-col p-5 gap-1" style={{ background: "#2E2E2E" }}>
        <div className="flex items-center gap-3 px-2 mb-6 mt-1">
          <img src={LOGO_KC} alt="KC Spa" className="w-11 h-11 rounded-xl" />
          <div><div className="text-white text-[17px] leading-tight" style={{ fontFamily: "'Fraunces', serif" }}>KC Spa</div><div className="text-gray-300 text-[11px]">panel de gestión</div></div>
        </div>
        <SelectorLocal />
        {NAV.map((it) => <NavBtn key={it.key} item={it} />)}
        <div className="mt-auto pt-4 px-2"><div className="pt-4 border-t border-white/10">
          <div className="text-white text-sm">{profile.nombre}</div>
          <div className="text-gray-300 text-xs mb-1">{ROLES[rol]}</div>
          <div className="text-xs mb-3" style={{ color: "#A9B9AA" }}>📍 {localNombre}</div>
          <button onClick={onLogout} className="text-xs hover:underline" style={{ color: "#E3A48E" }}>Cerrar sesión</button>
        </div></div>
      </aside>
      <main className="flex-1 p-4 sm:p-6 md:p-8 max-w-6xl pb-20 md:pb-8">{contenido()}</main>
    </div>
  );
}

function Proximamente({ titulo }) {
  return (
    <div>
      <SectionTitle eyebrow="Próximamente" title={titulo} />
      <Card className="p-8 text-center"><p className="text-sm text-[#7C8F7E]">Este módulo se conectará en el siguiente paso.<br />Ya funcionan sobre tu base real: Pacientes, Agenda, Maestros e Inventario.</p></Card>
    </div>
  );
}

// =====================================================================
//  Pacientes
// =====================================================================
function Pacientes({ api, P, localId, usuarioId }) {
  const [pacientes, setPacientes] = useState([]);
  const [alteraciones, setAlteraciones] = useState([]);
  const [busqueda, setBusqueda] = useState("");
  const [activo, setActivo] = useState(null);
  const [modal, setModal] = useState(null);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState("");

  const cargar = useCallback(async () => {
    setCargando(true); setError("");
    try {
      const [pac, alt] = await Promise.all([
        api.select("pacientes", `local_id=eq.${localId}&select=*,paciente_alteraciones(alteracion_id)&order=apellidos.asc`),
        api.select("alteraciones_piel", "select=*&order=nombre.asc"),
      ]);
      setPacientes(pac || []); setAlteraciones(alt || []);
    } catch (e) { setError("No se pudieron cargar los pacientes: " + e.message); }
    setCargando(false);
  }, [api, localId]);
  useEffect(() => { cargar(); setActivo(null); }, [cargar]);

  const nombreAlt = (id) => alteraciones.find((a) => a.id === id)?.nombre ?? "";
  const q = busqueda.trim().toLowerCase();
  const filtrados = useMemo(() => pacientes.filter((p) => !q || `${p.nombres} ${p.apellidos}`.toLowerCase().includes(q) || (p.cedula || "").includes(busqueda)), [pacientes, q, busqueda]);

  const guardar = async (form, altSel, editandoId) => {
    try {
      let pacienteId = editandoId;
      if (editandoId) {
        await api.update("pacientes", `id=eq.${editandoId}`, { ...form, actualizado_por: usuarioId });
      } else {
        const row = await api.insert("pacientes", { ...form, local_id: localId, creado_por: usuarioId });
        pacienteId = row.id;
      }
      if (P.pacAlteraciones) {
        await api.remove("paciente_alteraciones", `paciente_id=eq.${pacienteId}`);
        if (altSel.length) await api.insert("paciente_alteraciones", altSel.map((a) => ({ paciente_id: pacienteId, alteracion_id: a })));
      }
      setModal(null); await cargar(); return {};
    } catch (e) { return { error: e.message }; }
  };
  const eliminar = async (p) => {
    if (!confirm(`¿Eliminar a ${p.nombres} ${p.apellidos}?`)) return;
    try { await api.remove("paciente_alteraciones", `paciente_id=eq.${p.id}`); await api.remove("pacientes", `id=eq.${p.id}`); setActivo(null); await cargar(); }
    catch (e) { setError("No se pudo eliminar: " + e.message); }
  };

  if (cargando) return <div><SectionTitle eyebrow="Base de datos" title="Pacientes" /><Card className="p-8 text-center text-sm text-[#7C8F7E]">Cargando…</Card></div>;

  if (activo) {
    const p = pacientes.find((x) => x.id === activo);
    if (!p) { setActivo(null); return null; }
    const altN = (p.paciente_alteraciones || []).map((r) => nombreAlt(r.alteracion_id)).filter(Boolean);
    return (
      <div>
        <button onClick={() => setActivo(null)} className="flex items-center gap-1 text-[#7C9885] text-sm mb-5"><ChevronLeft size={16} />Volver</button>
        <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
          <div><h2 className="text-[24px] text-[#2E2E2E]" style={{ fontFamily: "'Fraunces', serif" }}>{p.nombres} {p.apellidos}</h2><div className="text-sm text-[#7C8F7E]">{p.cedula ? `CI/Pas.: ${p.cedula}` : ""}</div></div>
          <div className="flex gap-2">{P.pacEditar && <Boton variant="secondary" onClick={() => setModal(p)}>Editar</Boton>}{P.pacEliminar && <Boton variant="secondary" onClick={() => eliminar(p)}>Eliminar</Boton>}</div>
        </div>
        <Card className="p-5 mb-4">
          <div className="text-[12px] uppercase tracking-[0.12em] mb-3" style={{ color: "#7C9885", fontFamily: "'Sora', sans-serif" }}>Identificación</div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-2 text-sm">
            <Dato l="Sexo" v={p.sexo} /><Dato l="Nacimiento" v={p.fecha_nacimiento} /><Dato l="Teléfono" v={p.telefono} /><Dato l="Correo" v={p.correo} /><Dato l="Dirección" v={p.direccion} />
            <Dato l="Emergencia" v={p.emergencia_nombre ? `${p.emergencia_nombre} (${p.emergencia_parentesco || "—"}) · ${p.emergencia_telefono || "—"}` : ""} />
          </div>
        </Card>
        <Card className="p-5 mb-4">
          <div className="text-[12px] uppercase tracking-[0.12em] mb-3" style={{ color: "#7C9885", fontFamily: "'Sora', sans-serif" }}>Piel</div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-2 text-sm">
            <Dato l="Tipo de piel" v={etiquetaTipoPiel(p.tipo_piel)} />
            <div><span className="text-[#A9B9AA]">Alteraciones: </span><span className="text-[#2E2E2E]">{altN.length ? altN.join(", ") : "—"}</span></div>
          </div>
        </Card>
        {(p.enfermedades_cronicas || p.alergias || p.medicamentos) && (
          <Card className="p-5"><div className="text-[12px] uppercase tracking-[0.12em] mb-3" style={{ color: "#7C9885", fontFamily: "'Sora', sans-serif" }}>Antecedentes</div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-2 text-sm"><Dato l="Enfermedades crónicas" v={p.enfermedades_cronicas} /><Dato l="Alergias" v={p.alergias} /><Dato l="Medicamentos" v={p.medicamentos} /></div>
          </Card>
        )}
        {modal && <ModalPaciente paciente={modal === "nuevo" ? null : modal} alteraciones={alteraciones} puedeAlteraciones={P.pacAlteraciones} onClose={() => setModal(null)} onGuardar={guardar} />}
      </div>
    );
  }

  return (
    <div>
      <SectionTitle eyebrow="Base de datos" title="Pacientes" action={P.pacCrear ? <Boton onClick={() => setModal("nuevo")}><Plus size={16} />Nuevo paciente</Boton> : null} />
      {error && <Aviso>{error}</Aviso>}
      <div className="relative mb-4 max-w-sm"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#A9B9AA]" /><input value={busqueda} onChange={(e) => setBusqueda(e.target.value)} placeholder="Buscar por nombre o cédula…" className={`${inputClass} pl-9`} /></div>
      <Card className="overflow-x-auto">
        <table className="w-full text-sm" style={{ minWidth: "560px" }}>
          <thead><tr className="text-left text-[#7C8F7E] text-xs uppercase tracking-wide border-b border-[#EFE9DA]" style={{ fontFamily: "'Sora', sans-serif" }}><th className="px-3 py-2.5 font-medium">Nombre</th><th className="px-3 py-2.5 font-medium">CI / Pas.</th><th className="px-3 py-2.5 font-medium">Teléfono</th><th className="px-3 py-2.5 font-medium">Tipo de piel</th><th className="px-3 py-2.5 font-medium text-right">Ver</th></tr></thead>
          <tbody>
            {filtrados.map((p) => (
              <tr key={p.id} className="border-b border-[#F4EFE2] cursor-pointer hover:bg-[#FBF9F3]" onClick={() => setActivo(p.id)}>
                <td className="px-3 py-2.5 text-[#2E2E2E]">{p.nombres} {p.apellidos}</td><td className="px-3 py-2.5 text-[#7C8F7E]">{p.cedula || "—"}</td><td className="px-3 py-2.5 text-[#7C8F7E]">{p.telefono || "—"}</td><td className="px-3 py-2.5 text-[#7C8F7E]">{etiquetaTipoPiel(p.tipo_piel)}</td><td className="px-3 py-2.5 text-right"><span className="text-xs" style={{ color: "#7C9885" }}>Abrir →</span></td>
              </tr>
            ))}
            {filtrados.length === 0 && <tr><td colSpan={5} className="px-3 py-6 text-center text-[#7C8F7E]">No se encontraron pacientes.</td></tr>}
          </tbody>
        </table>
      </Card>
      {modal && <ModalPaciente paciente={modal === "nuevo" ? null : modal} alteraciones={alteraciones} puedeAlteraciones={P.pacAlteraciones} onClose={() => setModal(null)} onGuardar={guardar} />}
    </div>
  );
}
function Dato({ l, v }) { if (!v) return null; return <div><span className="text-[#A9B9AA]">{l}: </span><span className="text-[#2E2E2E]">{v}</span></div>; }

function ModalPaciente({ paciente, alteraciones, puedeAlteraciones, onClose, onGuardar }) {
  const [f, setF] = useState({
    cedula: paciente?.cedula ?? "", nombres: paciente?.nombres ?? "", apellidos: paciente?.apellidos ?? "",
    fecha_nacimiento: paciente?.fecha_nacimiento ?? "", sexo: paciente?.sexo ?? "", telefono: paciente?.telefono ?? "",
    correo: paciente?.correo ?? "", direccion: paciente?.direccion ?? "",
    emergencia_nombre: paciente?.emergencia_nombre ?? "", emergencia_parentesco: paciente?.emergencia_parentesco ?? "", emergencia_telefono: paciente?.emergencia_telefono ?? "",
    enfermedades_cronicas: paciente?.enfermedades_cronicas ?? "", alergias: paciente?.alergias ?? "", medicamentos: paciente?.medicamentos ?? "", tipo_piel: paciente?.tipo_piel ?? "",
  });
  const [alt, setAlt] = useState((paciente?.paciente_alteraciones || []).map((r) => r.alteracion_id));
  const [error, setError] = useState(""); const [guardando, setGuardando] = useState(false);
  const set = (k, v) => setF((p) => ({ ...p, [k]: v }));
  const toggleAlt = (id) => setAlt((a) => a.includes(id) ? a.filter((x) => x !== id) : [...a, id]);
  const submit = async () => {
    if (!f.nombres.trim() || !f.apellidos.trim()) { setError("Nombres y apellidos son obligatorios."); return; }
    setError(""); setGuardando(true);
    const payload = { ...f, tipo_piel: f.tipo_piel || null, cedula: f.cedula.trim() || null, fecha_nacimiento: f.fecha_nacimiento || null };
    const res = await onGuardar(payload, alt, paciente?.id); setGuardando(false);
    if (res?.error) setError(res.error);
  };
  return (
    <Modal title={paciente ? "Editar paciente" : "Nuevo paciente"} onClose={onClose} wide>
      <div className="text-[12px] tracking-[0.12em] uppercase mb-3" style={{ color: "#7C9885", fontFamily: "'Sora', sans-serif" }}>Identificación</div>
      <Field label="Cédula o pasaporte"><input value={f.cedula} onChange={(e) => set("cedula", e.target.value)} className={inputClass} /></Field>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4"><Field label="Nombres *"><input value={f.nombres} onChange={(e) => set("nombres", e.target.value)} className={inputClass} /></Field><Field label="Apellidos *"><input value={f.apellidos} onChange={(e) => set("apellidos", e.target.value)} className={inputClass} /></Field></div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4"><Field label="Fecha de nacimiento"><input type="date" value={f.fecha_nacimiento} onChange={(e) => set("fecha_nacimiento", e.target.value)} className={inputClass} /></Field><Field label="Sexo"><select value={f.sexo} onChange={(e) => set("sexo", e.target.value)} className={inputClass}><option value="">Seleccionar…</option><option>Femenino</option><option>Masculino</option><option>Otro</option></select></Field></div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4"><Field label="Teléfono"><input value={f.telefono} onChange={(e) => set("telefono", e.target.value)} className={inputClass} /></Field><Field label="Correo"><input type="email" value={f.correo} onChange={(e) => set("correo", e.target.value)} className={inputClass} /></Field></div>
      <Field label="Dirección"><input value={f.direccion} onChange={(e) => set("direccion", e.target.value)} className={inputClass} /></Field>
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4"><Field label="Contacto emergencia"><input value={f.emergencia_nombre} onChange={(e) => set("emergencia_nombre", e.target.value)} className={inputClass} /></Field><Field label="Parentesco"><input value={f.emergencia_parentesco} onChange={(e) => set("emergencia_parentesco", e.target.value)} className={inputClass} /></Field><Field label="Tel. emergencia"><input value={f.emergencia_telefono} onChange={(e) => set("emergencia_telefono", e.target.value)} className={inputClass} /></Field></div>
      <div className="border-t border-[#E7E1D2] my-4" />
      <div className="text-[12px] tracking-[0.12em] uppercase mb-3" style={{ color: "#7C9885", fontFamily: "'Sora', sans-serif" }}>Piel</div>
      <Field label="Tipo de piel"><select value={f.tipo_piel} onChange={(e) => set("tipo_piel", e.target.value)} className={inputClass}><option value="">Seleccionar…</option>{TIPOS_PIEL.map((t) => <option key={t} value={t}>{etiquetaTipoPiel(t)}</option>)}</select></Field>
      <div className="mb-4">
        <span className="block text-[13px] text-[#5E6E5F] mb-1.5" style={{ fontFamily: "'Sora', sans-serif" }}>Alteraciones de la piel</span>
        {!puedeAlteraciones && <p className="text-[11px] mb-2" style={{ color: "#A9B9AA" }}>Tu rol no puede editar alteraciones.</p>}
        <div className="flex flex-wrap gap-2">
          {alteraciones.map((a) => { const sel = alt.includes(a.id); return (
            <button key={a.id} type="button" disabled={!puedeAlteraciones} onClick={() => toggleAlt(a.id)} className="text-xs px-3 py-1.5 rounded-full border disabled:opacity-60" style={sel ? { backgroundColor: "#7C9885", color: "#fff", borderColor: "#7C9885" } : { backgroundColor: "#fff", color: "#5E6E5F", borderColor: "#DDD6C2" }}>{sel && <Check size={12} className="inline mr-1" />}{a.nombre}</button>
          ); })}
          {alteraciones.length === 0 && <span className="text-xs" style={{ color: "#A9B9AA" }}>No hay alteraciones registradas en la tabla alteraciones_piel.</span>}
        </div>
      </div>
      <div className="border-t border-[#E7E1D2] my-4" />
      <div className="text-[12px] tracking-[0.12em] uppercase mb-3" style={{ color: "#7C9885", fontFamily: "'Sora', sans-serif" }}>Antecedentes</div>
      <Field label="Enfermedades crónicas"><textarea value={f.enfermedades_cronicas} onChange={(e) => set("enfermedades_cronicas", e.target.value)} rows={2} className={inputClass} /></Field>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4"><Field label="Alergias"><textarea value={f.alergias} onChange={(e) => set("alergias", e.target.value)} rows={2} className={inputClass} /></Field><Field label="Medicamentos"><textarea value={f.medicamentos} onChange={(e) => set("medicamentos", e.target.value)} rows={2} className={inputClass} /></Field></div>
      {error && <Aviso>{error}</Aviso>}
      <Boton onClick={submit} disabled={guardando}>{guardando ? "Guardando…" : "Guardar paciente"}</Boton>
    </Modal>
  );
}

// =====================================================================
//  Inventario
// =====================================================================
function Inventario({ api, P, localId }) {
  const [items, setItems] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState("");
  const [filtro, setFiltro] = useState("todos"); const [busqueda, setBusqueda] = useState("");
  const puedeDisminuir = P.invDisminuir;

  const cargar = useCallback(async () => {
    setCargando(true); setError("");
    try { setItems(await api.select("inventario", `local_id=eq.${localId}&select=*&order=nombre.asc`) || []); }
    catch (e) { setError("No se pudo cargar el inventario: " + e.message); }
    setCargando(false);
  }, [api, localId]);
  useEffect(() => { cargar(); }, [cargar]);

  const ajustar = async (item, delta) => {
    const nuevo = Math.max(0, Number(item.stock) + delta);
    try { await api.update("inventario", `id=eq.${item.id}`, { stock: nuevo }); setItems((xs) => xs.map((x) => x.id === item.id ? { ...x, stock: nuevo } : x)); }
    catch (e) { setError(delta < 0 ? "Tu rol solo puede aumentar el inventario, no disminuirlo." : e.message); }
  };
  const q = busqueda.trim().toLowerCase();
  const lista = items.filter((i) => (filtro === "todos" || i.tipo === filtro) && (!q || i.nombre.toLowerCase().includes(q) || (i.categoria || "").toLowerCase().includes(q)))
    .sort((a, b) => { const ab = Number(a.stock) <= Number(a.stock_minimo), bb = Number(b.stock) <= Number(b.stock_minimo); if (ab !== bb) return ab ? -1 : 1; return a.nombre.localeCompare(b.nombre); });
  const bajos = items.filter((i) => Number(i.stock) <= Number(i.stock_minimo)).length;

  if (cargando) return <div><SectionTitle eyebrow="Stock" title="Inventario" /><Card className="p-8 text-center text-sm text-[#7C8F7E]">Cargando…</Card></div>;
  return (
    <div>
      <SectionTitle eyebrow="Stock" title="Inventario" />
      {error && <Aviso>{error}</Aviso>}
      <p className="text-xs text-[#7C8F7E] mb-4">{puedeDisminuir ? "Ajusta el stock con ±. Los ítems se crean en Maestros." : "Tu rol solo puede AUMENTAR el stock."}</p>
      {bajos > 0 && <Aviso>{bajos} ítem(s) por debajo del stock mínimo.</Aviso>}
      <div className="flex flex-wrap items-center gap-2 mb-3">
        <div className="relative flex-1 min-w-[180px] max-w-sm"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#A9B9AA]" /><input value={busqueda} onChange={(e) => setBusqueda(e.target.value)} placeholder="Buscar…" className={`${inputClass} pl-9`} /></div>
        {[["todos", "Todos"], ["insumo", "Insumos"], ["producto", "Productos"]].map(([v, t]) => <button key={v} onClick={() => setFiltro(v)} className="px-3 py-1.5 rounded-lg text-sm border" style={filtro === v ? { backgroundColor: "#2E2E2E", color: "#fff", borderColor: "#2E2E2E" } : { backgroundColor: "#fff", color: "#7C8F7E", borderColor: "#DDD6C2" }}>{t}</button>)}
      </div>
      <Card className="overflow-x-auto">
        <table className="w-full text-sm" style={{ minWidth: "640px" }}>
          <thead><tr className="text-left text-[#7C8F7E] text-xs uppercase tracking-wide border-b border-[#EFE9DA]" style={{ fontFamily: "'Sora', sans-serif" }}><th className="px-3 py-2.5 font-medium">Nombre</th><th className="px-3 py-2.5 font-medium">Tipo</th><th className="px-3 py-2.5 font-medium">Categoría</th><th className="px-3 py-2.5 font-medium text-right">Precio</th><th className="px-3 py-2.5 font-medium text-right">Stock</th><th className="px-3 py-2.5 font-medium text-right">Mínimo</th><th className="px-3 py-2.5 font-medium text-center">Ajustar</th></tr></thead>
          <tbody>
            {lista.map((i) => { const bajo = Number(i.stock) <= Number(i.stock_minimo); const prod = i.tipo === "producto"; return (
              <tr key={i.id} className="border-b border-[#F4EFE2]" style={bajo ? { backgroundColor: "#FCF3EC" } : undefined}>
                <td className="px-3 py-2.5 text-[#2E2E2E]">{i.nombre}{bajo && <span className="ml-2 text-[10px]" style={{ color: "#B4694F" }}>● bajo</span>}</td>
                <td className="px-3 py-2.5"><span className="text-[10px] px-2 py-0.5 rounded-full" style={prod ? { backgroundColor: "#EEE9DC", color: "#6A6152" } : { backgroundColor: "#E6EFE6", color: "#4A7350" }}>{prod ? "Producto" : "Insumo"}</span></td>
                <td className="px-3 py-2.5 text-[#7C8F7E]">{i.categoria || "—"}</td>
                <td className="px-3 py-2.5 text-right text-[#7C8F7E]">{prod ? `$${Number(i.precio).toFixed(2)}` : "—"}</td>
                <td className="px-3 py-2.5 text-right" style={{ color: bajo ? "#B4694F" : "#2E2E2E" }}>{i.stock} {i.unidad}</td>
                <td className="px-3 py-2.5 text-right text-[#7C8F7E]">{i.stock_minimo}</td>
                <td className="px-3 py-2.5"><div className="flex items-center justify-center gap-1">
                  <button onClick={() => ajustar(i, -1)} disabled={!puedeDisminuir} className="w-7 h-7 rounded-md border border-[#DDD6C2] bg-white flex items-center justify-center text-[#2E2E2E] hover:bg-[#F6F1E4] disabled:opacity-30"><Minus size={13} /></button>
                  <button onClick={() => ajustar(i, 1)} className="w-7 h-7 rounded-md border border-[#DDD6C2] bg-white flex items-center justify-center text-[#2E2E2E] hover:bg-[#F6F1E4]"><Plus size={13} /></button>
                </div></td>
              </tr>
            ); })}
            {lista.length === 0 && <tr><td colSpan={7} className="px-3 py-6 text-center text-[#7C8F7E]">Sin ítems. Créalos en Maestros.</td></tr>}
          </tbody>
        </table>
      </Card>
    </div>
  );
}

// =====================================================================
//  Maestros
// =====================================================================
function Maestros({ api, localId }) {
  const [seccion, setSeccion] = useState("tratamientos");
  const [servicios, setServicios] = useState([]); const [inventario, setInventario] = useState([]);
  const [cargando, setCargando] = useState(true); const [error, setError] = useState("");
  const [modalServ, setModalServ] = useState(null); const [modalItem, setModalItem] = useState(null);

  const cargar = useCallback(async () => {
    setCargando(true); setError("");
    try {
      const [sv, inv] = await Promise.all([
        api.select("servicios", `local_id=eq.${localId}&select=*,servicio_insumos(insumo_id,cantidad)&order=nombre.asc`),
        api.select("inventario", `local_id=eq.${localId}&select=*&order=nombre.asc`),
      ]);
      setServicios(sv || []); setInventario(inv || []);
    } catch (e) { setError(e.message); }
    setCargando(false);
  }, [api, localId]);
  useEffect(() => { cargar(); }, [cargar]);

  const insumos = inventario.filter((i) => i.tipo === "insumo");
  const productos = inventario.filter((i) => i.tipo === "producto");
  const nombreInsumo = (id) => insumos.find((i) => i.id === id)?.nombre ?? "—";

  const guardarServicio = async (form, bom, id) => {
    try {
      let servId = id;
      if (id) await api.update("servicios", `id=eq.${id}`, form);
      else { const row = await api.insert("servicios", { ...form, local_id: localId, activo: true }); servId = row.id; }
      await api.remove("servicio_insumos", `servicio_id=eq.${servId}`);
      if (bom.length) await api.insert("servicio_insumos", bom.map((b) => ({ servicio_id: servId, insumo_id: b.insumo_id, cantidad: b.cantidad })));
      setModalServ(null); await cargar(); return {};
    } catch (e) { return { error: e.message }; }
  };
  const eliminarServicio = async (s) => { if (!confirm(`¿Eliminar "${s.nombre}"?`)) return; try { await api.remove("servicio_insumos", `servicio_id=eq.${s.id}`); await api.remove("servicios", `id=eq.${s.id}`); cargar(); } catch (e) { setError(e.message); } };
  const guardarItem = async (form, id) => { try { if (id) await api.update("inventario", `id=eq.${id}`, form); else await api.insert("inventario", { ...form, local_id: localId }); setModalItem(null); await cargar(); return {}; } catch (e) { return { error: e.message }; } };
  const eliminarItem = async (it) => { if (!confirm(`¿Eliminar "${it.nombre}"?`)) return; try { await api.remove("inventario", `id=eq.${it.id}`); cargar(); } catch (e) { setError(e.message); } };

  const tabBtn = (v, t) => <button key={v} onClick={() => setSeccion(v)} className="px-3 py-1.5 rounded-lg text-sm border" style={seccion === v ? { backgroundColor: "#2E2E2E", color: "#fff", borderColor: "#2E2E2E" } : { backgroundColor: "#fff", color: "#7C8F7E", borderColor: "#DDD6C2" }}>{t}</button>;
  if (cargando) return <div><SectionTitle eyebrow="Catálogos" title="Maestros" /><Card className="p-8 text-center text-sm text-[#7C8F7E]">Cargando…</Card></div>;
  const accion = seccion === "tratamientos" ? <Boton onClick={() => setModalServ("nuevo")}><Plus size={16} />Nuevo tratamiento</Boton> : <Boton onClick={() => setModalItem({ tipo: seccion === "insumos" ? "insumo" : "producto" })}><Plus size={16} />Nuevo {seccion === "insumos" ? "insumo" : "producto"}</Boton>;

  return (
    <div>
      <SectionTitle eyebrow="Catálogos" title="Maestros" action={accion} />
      {error && <Aviso>{error}</Aviso>}
      <div className="flex flex-wrap gap-2 mb-4">{tabBtn("tratamientos", "Tratamientos")}{tabBtn("insumos", "Insumos")}{tabBtn("productos", "Productos")}</div>
      {seccion === "tratamientos" && (
        <Card className="overflow-x-auto"><table className="w-full text-sm" style={{ minWidth: "620px" }}>
          <thead><tr className="text-left text-[#7C8F7E] text-xs uppercase tracking-wide border-b border-[#EFE9DA]" style={{ fontFamily: "'Sora', sans-serif" }}><th className="px-3 py-2.5 font-medium">Código</th><th className="px-3 py-2.5 font-medium">Tratamiento</th><th className="px-3 py-2.5 font-medium text-right">Duración</th><th className="px-3 py-2.5 font-medium text-right">Precio</th><th className="px-3 py-2.5 font-medium">Insumos</th><th className="px-3 py-2.5 font-medium text-right">Acciones</th></tr></thead>
          <tbody>
            {servicios.map((s) => (
              <tr key={s.id} className="border-b border-[#F4EFE2]"><td className="px-3 py-2.5 font-mono text-xs text-[#7C9885]">{s.codigo || "—"}</td><td className="px-3 py-2.5 text-[#2E2E2E]">{s.nombre}</td><td className="px-3 py-2.5 text-right text-[#7C8F7E]">{s.duracion} min</td><td className="px-3 py-2.5 text-right text-[#2E2E2E]">${Number(s.precio).toFixed(2)}</td><td className="px-3 py-2.5 text-xs text-[#7C9885]">{(s.servicio_insumos || []).length ? s.servicio_insumos.map((b) => `${b.cantidad} ${nombreInsumo(b.insumo_id)}`).join(", ") : "—"}</td><td className="px-3 py-2.5 text-right whitespace-nowrap"><button onClick={() => setModalServ(s)} className="text-xs mr-3" style={{ color: "#7C9885" }}>Editar</button><button onClick={() => eliminarServicio(s)} className="text-xs" style={{ color: "#B4694F" }}>Eliminar</button></td></tr>
            ))}
            {servicios.length === 0 && <tr><td colSpan={6} className="px-3 py-6 text-center text-[#7C8F7E]">Sin tratamientos.</td></tr>}
          </tbody>
        </table></Card>
      )}
      {(seccion === "insumos" || seccion === "productos") && (
        <Card className="overflow-x-auto"><table className="w-full text-sm" style={{ minWidth: "620px" }}>
          <thead><tr className="text-left text-[#7C8F7E] text-xs uppercase tracking-wide border-b border-[#EFE9DA]" style={{ fontFamily: "'Sora', sans-serif" }}><th className="px-3 py-2.5 font-medium">Código</th><th className="px-3 py-2.5 font-medium">Nombre</th><th className="px-3 py-2.5 font-medium">Categoría</th><th className="px-3 py-2.5 font-medium">Unidad</th>{seccion === "productos" ? <th className="px-3 py-2.5 font-medium text-right">Precio</th> : <th className="px-3 py-2.5 font-medium text-right">Stock mín.</th>}<th className="px-3 py-2.5 font-medium text-right">Acciones</th></tr></thead>
          <tbody>
            {(seccion === "insumos" ? insumos : productos).map((i) => (
              <tr key={i.id} className="border-b border-[#F4EFE2]"><td className="px-3 py-2.5 font-mono text-xs text-[#7C9885]">{i.codigo || "—"}</td><td className="px-3 py-2.5 text-[#2E2E2E]">{i.nombre}</td><td className="px-3 py-2.5 text-[#7C8F7E]">{i.categoria || "—"}</td><td className="px-3 py-2.5 text-[#7C8F7E]">{i.unidad}</td>{seccion === "productos" ? <td className="px-3 py-2.5 text-right text-[#2E2E2E]">${Number(i.precio).toFixed(2)}</td> : <td className="px-3 py-2.5 text-right text-[#7C8F7E]">{i.stock_minimo}</td>}<td className="px-3 py-2.5 text-right whitespace-nowrap"><button onClick={() => setModalItem(i)} className="text-xs mr-3" style={{ color: "#7C9885" }}>Editar</button><button onClick={() => eliminarItem(i)} className="text-xs" style={{ color: "#B4694F" }}>Eliminar</button></td></tr>
            ))}
            {(seccion === "insumos" ? insumos : productos).length === 0 && <tr><td colSpan={6} className="px-3 py-6 text-center text-[#7C8F7E]">Sin {seccion}.</td></tr>}
          </tbody>
        </table></Card>
      )}
      {modalServ && <ModalServicio servicio={modalServ === "nuevo" ? null : modalServ} insumos={insumos} onClose={() => setModalServ(null)} onGuardar={guardarServicio} />}
      {modalItem && <ModalItemInv item={modalItem.tipo ? null : modalItem} tipoFijo={modalItem.tipo} onClose={() => setModalItem(null)} onGuardar={guardarItem} />}
    </div>
  );
}

function ModalServicio({ servicio, insumos, onClose, onGuardar }) {
  const [codigo, setCodigo] = useState(servicio?.codigo ?? ""); const [nombre, setNombre] = useState(servicio?.nombre ?? "");
  const [duracion, setDuracion] = useState(servicio?.duracion ?? 30); const [precio, setPrecio] = useState(servicio?.precio ?? "");
  const [bom, setBom] = useState((servicio?.servicio_insumos || []).map((b) => ({ insumo_id: b.insumo_id, cantidad: b.cantidad })));
  const [error, setError] = useState(""); const [guardando, setGuardando] = useState(false);
  const addBom = () => setBom((b) => [...b, { insumo_id: insumos[0]?.id ?? "", cantidad: 1 }]);
  const setRow = (i, k, v) => setBom((b) => b.map((r, j) => j === i ? { ...r, [k]: v } : r));
  const delRow = (i) => setBom((b) => b.filter((_, j) => j !== i));
  const submit = async () => {
    if (!nombre.trim()) { setError("Escribe el nombre."); return; }
    if (precio === "") { setError("Indica el precio."); return; }
    setError(""); setGuardando(true);
    const res = await onGuardar({ codigo: codigo.trim() || null, nombre: nombre.trim(), duracion: parseInt(duracion) || 0, precio: parseFloat(precio) || 0 }, bom.filter((r) => r.insumo_id), servicio?.id);
    setGuardando(false); if (res?.error) setError(res.error);
  };
  return (
    <Modal title={servicio ? "Editar tratamiento" : "Nuevo tratamiento"} onClose={onClose}>
      <div className="grid grid-cols-3 gap-3"><Field label="Código"><input value={codigo} onChange={(e) => setCodigo(e.target.value)} className={inputClass} placeholder="SERV-001" /></Field><div className="col-span-2"><Field label="Nombre"><input value={nombre} onChange={(e) => setNombre(e.target.value)} className={inputClass} autoFocus /></Field></div></div>
      <div className="grid grid-cols-2 gap-3"><Field label="Duración (min)"><input type="number" min="0" step="5" value={duracion} onChange={(e) => setDuracion(e.target.value)} className={inputClass} /></Field><Field label="Precio (USD)"><input type="number" min="0" step="0.5" value={precio} onChange={(e) => setPrecio(e.target.value)} className={inputClass} /></Field></div>
      <div className="mb-4">
        <div className="flex items-center justify-between mb-1.5"><span className="text-[13px] text-[#5E6E5F]" style={{ fontFamily: "'Sora', sans-serif" }}>Insumos que consume</span><button onClick={addBom} className="text-xs text-[#7C9885]">+ Agregar</button></div>
        {bom.length === 0 && <p className="text-xs text-[#A9B9AA]">Ninguno.</p>}
        <div className="space-y-2">{bom.map((r, i) => (
          <div key={i} className="flex items-center gap-2"><select value={r.insumo_id} onChange={(e) => setRow(i, "insumo_id", e.target.value)} className={inputClass} style={{ flex: "1 1 auto", minWidth: 0 }}>{insumos.map((x) => <option key={x.id} value={x.id}>{x.nombre} ({x.unidad})</option>)}</select><input type="number" min="0" step="0.1" value={r.cantidad} onChange={(e) => setRow(i, "cantidad", parseFloat(e.target.value) || 0)} className={inputClass} style={{ width: "56px", flex: "0 0 56px" }} /><button onClick={() => delRow(i)} className="text-[#B4694F] shrink-0"><X size={16} /></button></div>
        ))}</div>
      </div>
      {error && <Aviso>{error}</Aviso>}
      <Boton onClick={submit} disabled={guardando}>{guardando ? "Guardando…" : "Guardar"}</Boton>
    </Modal>
  );
}

function ModalItemInv({ item, tipoFijo, onClose, onGuardar }) {
  const [tipo, setTipo] = useState(item?.tipo ?? tipoFijo ?? "insumo");
  const [codigo, setCodigo] = useState(item?.codigo ?? ""); const [nombre, setNombre] = useState(item?.nombre ?? "");
  const [categoria, setCategoria] = useState(item?.categoria ?? ""); const [unidad, setUnidad] = useState(item?.unidad ?? "unidades");
  const [stock, setStock] = useState(item?.stock ?? ""); const [stockMin, setStockMin] = useState(item?.stock_minimo ?? ""); const [precio, setPrecio] = useState(item?.precio ?? "");
  const [error, setError] = useState(""); const [guardando, setGuardando] = useState(false);
  const submit = async () => {
    if (!nombre.trim() || stock === "" || stockMin === "") { setError("Completa nombre, stock y stock mínimo."); return; }
    if (tipo === "producto" && precio === "") { setError("Un producto necesita precio."); return; }
    setError(""); setGuardando(true);
    const res = await onGuardar({ tipo, codigo: codigo.trim() || null, nombre: nombre.trim(), categoria: categoria.trim() || null, unidad, stock: parseFloat(stock) || 0, stock_minimo: parseFloat(stockMin) || 0, precio: tipo === "producto" ? (parseFloat(precio) || 0) : 0 }, item?.id);
    setGuardando(false); if (res?.error) setError(res.error);
  };
  return (
    <Modal title={item ? "Editar ítem" : `Nuevo ${tipo}`} onClose={onClose}>
      <div className="grid grid-cols-3 gap-3"><Field label="Código"><input value={codigo} onChange={(e) => setCodigo(e.target.value)} className={inputClass} placeholder={tipo === "producto" ? "PRD-001" : "INS-001"} /></Field><div className="col-span-2"><Field label="Tipo"><select value={tipo} onChange={(e) => setTipo(e.target.value)} className={inputClass} disabled={!!tipoFijo && !item}><option value="insumo">Insumo</option><option value="producto">Producto</option></select></Field></div></div>
      <Field label="Nombre"><input value={nombre} onChange={(e) => setNombre(e.target.value)} className={inputClass} autoFocus /></Field>
      <div className="grid grid-cols-2 gap-3"><Field label="Categoría"><input value={categoria} onChange={(e) => setCategoria(e.target.value)} className={inputClass} placeholder="General" /></Field><Field label="Unidad"><select value={unidad} onChange={(e) => setUnidad(e.target.value)} className={inputClass}>{UNIDADES.map((u) => <option key={u}>{u}</option>)}</select></Field></div>
      {tipo === "producto" && <Field label="Precio de venta (USD)"><input type="number" min="0" step="0.5" value={precio} onChange={(e) => setPrecio(e.target.value)} className={inputClass} /></Field>}
      <div className="grid grid-cols-2 gap-3"><Field label={item ? "Stock actual" : "Stock inicial"}><input type="number" min="0" step="1" value={stock} onChange={(e) => setStock(e.target.value)} className={inputClass} /></Field><Field label="Stock mínimo"><input type="number" min="0" step="1" value={stockMin} onChange={(e) => setStockMin(e.target.value)} className={inputClass} /></Field></div>
      {error && <Aviso>{error}</Aviso>}
      <Boton onClick={submit} disabled={guardando}>{guardando ? "Guardando…" : "Guardar"}</Boton>
    </Modal>
  );
}

// =====================================================================
//  Agenda
// =====================================================================
function Agenda({ api, localId, usuarioId }) {
  const [citas, setCitas] = useState([]); const [profesionales, setProfesionales] = useState([]); const [servicios, setServicios] = useState([]);
  const [cargando, setCargando] = useState(true); const [error, setError] = useState("");
  const [vista, setVista] = useState("dia"); const [ancla, setAncla] = useState(_hoyISO());
  const [buscar, setBuscar] = useState(""); const [estadoF, setEstadoF] = useState("todas"); const [modal, setModal] = useState(null);

  const cargar = useCallback(async () => {
    setCargando(true); setError("");
    try {
      const [cit, prof, serv] = await Promise.all([
        api.select("citas", `local_id=eq.${localId}&select=*,cita_tratamientos(id,servicio_id,nombre,precio)&order=fecha.asc&order=hora.asc`),
        api.select("usuarios", "rol=eq.cosmetologa&select=id,nombre,profesional,rol"),
        api.select("servicios", `local_id=eq.${localId}&select=id,nombre,precio,duracion&order=nombre.asc`),
      ]);
      setCitas(cit || []); setProfesionales(prof || []); setServicios(serv || []);
    } catch (e) { setError("No se pudieron cargar las citas: " + e.message); }
    setCargando(false);
  }, [api, localId]);
  useEffect(() => { cargar(); }, [cargar]);

  const nombreProf = (id) => { const p = profesionales.find((x) => x.id === id); return p ? (p.profesional || p.nombre) : "Sin asignar"; };
  const [desde, hasta] = _rango(ancla, vista);
  const hayBusqueda = buscar.trim().length > 0; const q = buscar.trim().toLowerCase();
  const visibles = useMemo(() => citas.filter((c) => estadoF === "todas" || c.estado === estadoF).filter((c) => hayBusqueda || (c.fecha >= desde && c.fecha <= hasta)).filter((c) => !hayBusqueda || (c.nombre || "").toLowerCase().includes(q) || (c.telefono || "").includes(buscar)), [citas, estadoF, hayBusqueda, q, buscar, desde, hasta]);
  const porFecha = useMemo(() => { const m = {}; visibles.forEach((c) => { (m[c.fecha] = m[c.fecha] || []).push(c); }); return Object.entries(m).sort(([a], [b]) => a.localeCompare(b)); }, [visibles]);

  const cambiarEstado = async (c, estado) => { try { await api.update("citas", `id=eq.${c.id}`, { estado }); setCitas((xs) => xs.map((x) => x.id === c.id ? { ...x, estado } : x)); } catch (e) { setError(e.message); } };
  const toggleContactado = async (c) => { try { await api.update("citas", `id=eq.${c.id}`, { contactado: !c.contactado }); setCitas((xs) => xs.map((x) => x.id === c.id ? { ...x, contactado: !c.contactado } : x)); } catch (e) { setError(e.message); } };
  const eliminar = async (c) => { if (!confirm("¿Eliminar esta cita?")) return; try { await api.remove("cita_tratamientos", `cita_id=eq.${c.id}`); await api.remove("citas", `id=eq.${c.id}`); setCitas((xs) => xs.filter((x) => x.id !== c.id)); } catch (e) { setError(e.message); } };

  const guardar = async (form, servSel, editandoId) => {
    try {
      const fila = { local_id: localId, nombre: form.nombre.trim() || null, telefono: form.telefono.trim() || null, profesional_id: form.profesional_id || null, fecha: form.fecha, hora: form.hora, duracion: parseInt(form.duracion) || 60 };
      let citaId = editandoId;
      if (editandoId) await api.update("citas", `id=eq.${editandoId}`, fila);
      else { const row = await api.insert("citas", { ...fila, estado: "pendiente", contactado: false, creado_por: usuarioId || null }); citaId = row.id; }
      await api.remove("cita_tratamientos", `cita_id=eq.${citaId}`);
      if (servSel) { const s = servicios.find((x) => x.id === servSel); if (s) await api.insert("cita_tratamientos", { cita_id: citaId, servicio_id: s.id, nombre: s.nombre, precio: s.precio }); }
      setModal(null); await cargar(); return {};
    } catch (e) { return { error: e.message }; }
  };

  const etiquetaRango = vista === "dia" ? _diaLargo(ancla) : vista === "semana" ? `Semana del ${_diaLargo(desde)}` : _mesLargo(ancla);
  const PROFS = profesionales.length ? profesionales.map((p) => p.id) : [null];
  if (cargando) return <div><SectionTitle eyebrow="Citas" title="Agenda" /><Card className="p-8 text-center text-sm text-[#7C8F7E]">Cargando…</Card></div>;

  return (
    <div>
      <SectionTitle eyebrow="Citas" title="Agenda" action={<Boton onClick={() => setModal("nuevo")}><Plus size={16} />Nueva cita</Boton>} />
      {error && <Aviso>{error}</Aviso>}
      <div className="flex flex-wrap items-center gap-2 mb-3">
        {[["dia", "Diaria"], ["semana", "Semanal"], ["mes", "Mensual"]].map(([v, t]) => <button key={v} onClick={() => setVista(v)} className="px-3 py-1.5 rounded-lg text-sm border" style={vista === v ? { backgroundColor: "#2E2E2E", color: "#fff", borderColor: "#2E2E2E" } : { backgroundColor: "#fff", color: "#7C8F7E", borderColor: "#DDD6C2" }}>{t}</button>)}
        <div className="flex items-center gap-1 ml-auto">
          <button onClick={() => setAncla(_mover(ancla, vista, -1))} className="w-8 h-8 rounded-lg border flex items-center justify-center" style={{ borderColor: "#DDD6C2", color: "#7C8F7E" }}><ChevronLeft size={16} /></button>
          <button onClick={() => setAncla(_hoyISO())} className="px-3 h-8 rounded-lg border text-sm" style={{ borderColor: "#DDD6C2", color: "#7C8F7E" }}>Hoy</button>
          <button onClick={() => setAncla(_mover(ancla, vista, 1))} className="w-8 h-8 rounded-lg border flex items-center justify-center" style={{ borderColor: "#DDD6C2", color: "#7C8F7E" }}><ChevronLeft size={16} style={{ transform: "rotate(180deg)" }} /></button>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-3 mb-4">
        <div className="relative flex-1 min-w-[180px] max-w-xs"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#A9B9AA]" /><input value={buscar} onChange={(e) => setBuscar(e.target.value)} placeholder="Buscar por nombre o teléfono…" className={`${inputClass} pl-9`} /></div>
        <select value={estadoF} onChange={(e) => setEstadoF(e.target.value)} className={inputClass} style={{ width: "auto", minWidth: "150px" }}><option value="todas">Todos los estados</option><option value="pendiente">Pendientes</option><option value="atendida">Atendidas</option><option value="cancelada">Canceladas</option></select>
        <div className="flex items-center gap-1"><span className="text-xs" style={{ color: "#7C8F7E" }}>Ir a fecha:</span><input type="date" value={ancla} onChange={(e) => { if (e.target.value) { setAncla(e.target.value); setVista("dia"); } }} className={inputClass} style={{ width: "auto" }} /></div>
      </div>
      <div className="text-sm mb-4 capitalize" style={{ color: "#7C9885", fontFamily: "'Sora', sans-serif" }}>{hayBusqueda ? `Resultados para "${buscar}"` : etiquetaRango}</div>
      {porFecha.length === 0 && <Card className="p-8 text-center text-sm text-[#7C8F7E]">No hay citas en este periodo.</Card>}
      <div className="space-y-6">
        {porFecha.map(([fecha, lista]) => (
          <Card key={fecha} className="p-5">
            <h3 className="text-[16px] text-[#2E2E2E] mb-4 capitalize" style={{ fontFamily: "'Fraunces', serif" }}>{_diaLargo(fecha)}</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {PROFS.map((pid) => { const cs = lista.filter((c) => (c.profesional_id || null) === pid).sort((a, b) => _aMin(a.hora) - _aMin(b.hora)); return (
                <div key={pid || "sin"} className="rounded-xl border border-[#E7E1D2] p-3" style={{ backgroundColor: "#FBF9F3" }}>
                  <div className="flex items-center gap-2 mb-2 px-1"><span className="w-2 h-2 rounded-full" style={{ backgroundColor: "#7C9885" }} /><span className="text-sm" style={{ fontFamily: "'Sora', sans-serif", color: "#2E2E2E" }}>{nombreProf(pid)}</span><span className="text-xs ml-auto" style={{ color: "#A9B9AA" }}>{cs.length} cita(s)</span></div>
                  {cs.length === 0 && <p className="text-xs px-1 py-2" style={{ color: "#A9B9AA" }}>Sin citas</p>}
                  <div className="space-y-1">{cs.map((c) => { const est = ESTADO_CITA[c.estado] || ESTADO_CITA.pendiente; const trat = (c.cita_tratamientos || [])[0]; return (
                    <div key={c.id} className="py-2 px-2 rounded-lg hover:bg-white text-sm">
                      <div className="flex items-center gap-2"><span className="shrink-0 font-medium" style={{ color: "#2E2E2E", fontFamily: "'Sora', sans-serif" }}>{c.hora}–{_horaFin(c.hora, c.duracion)}</span><span className="text-[#2E2E2E] truncate">{c.nombre || "—"}</span>{c.telefono && <span className="text-xs shrink-0" style={{ color: "#A9B9AA" }}>· {c.telefono}</span>}<span className="text-[10px] px-1.5 py-0.5 rounded-full ml-auto shrink-0" style={{ backgroundColor: est.bg, color: est.fg }}>{est.t}</span></div>
                      <div className="flex items-center justify-between mt-0.5 gap-2"><span className="text-xs" style={{ color: "#7C8F7E" }}>{trat ? `${trat.nombre} · ` : ""}{c.duracion} min</span>
                        <div className="flex gap-2 shrink-0 flex-wrap justify-end">
                          <button onClick={() => toggleContactado(c)} className="text-xs" style={{ color: c.contactado ? "#7C9885" : "#A9B9AA" }}>{c.contactado ? "✓ contactado" : "contactar"}</button>
                          <button onClick={() => setModal(c)} className="text-xs" style={{ color: "#7C9885" }}>Editar</button>
                          {c.estado !== "cancelada" ? <button onClick={() => cambiarEstado(c, "cancelada")} className="text-xs" style={{ color: "#B4694F" }}>Cancelar</button> : <button onClick={() => cambiarEstado(c, "pendiente")} className="text-xs" style={{ color: "#7C9885" }}>Reactivar</button>}
                          <button onClick={() => eliminar(c)} className="text-xs" style={{ color: "#B4694F" }}>Eliminar</button>
                        </div>
                      </div>
                    </div>
                  ); })}</div>
                </div>
              ); })}
            </div>
          </Card>
        ))}
      </div>
      {modal && <ModalCita cita={modal === "nuevo" ? null : modal} profesionales={profesionales} servicios={servicios} citas={citas} onClose={() => setModal(null)} onGuardar={guardar} />}
    </div>
  );
}

function ModalCita({ cita, profesionales, servicios, citas, onClose, onGuardar }) {
  const trat = (cita?.cita_tratamientos || [])[0];
  const [nombre, setNombre] = useState(cita?.nombre ?? ""); const [telefono, setTelefono] = useState(cita?.telefono ?? "");
  const [profesionalId, setProfesionalId] = useState(cita?.profesional_id ?? ""); const [servicioId, setServicioId] = useState(trat?.servicio_id ?? "");
  const [fecha, setFecha] = useState(cita?.fecha ?? _hoyISO()); const [hora, setHora] = useState(cita?.hora ?? "10:00"); const [duracion, setDuracion] = useState(cita?.duracion ?? 60);
  const [error, setError] = useState(""); const [guardando, setGuardando] = useState(false);
  const elegirServicio = (id) => { setServicioId(id); const s = servicios.find((x) => x.id === id); if (s?.duracion) setDuracion(s.duracion); };
  const cruce = useMemo(() => { if (!profesionalId) return null; const ini = _aMin(hora), fin = ini + (parseInt(duracion) || 0); return citas.find((c) => c.id !== cita?.id && c.profesional_id === profesionalId && c.fecha === fecha && c.estado !== "cancelada" && _aMin(c.hora) < fin && (_aMin(c.hora) + (parseInt(c.duracion) || 0)) > ini) || null; }, [profesionalId, hora, duracion, fecha, citas, cita]);
  const submit = async () => {
    if (!nombre.trim()) { setError("Escribe al menos el nombre."); return; }
    setError(""); setGuardando(true);
    const res = await onGuardar({ nombre, telefono, profesional_id: profesionalId, fecha, hora, duracion }, servicioId, cita?.id);
    setGuardando(false); if (res?.error) setError(res.error);
  };
  return (
    <Modal title={cita ? "Editar cita" : "Nueva cita"} onClose={onClose}>
      <p className="text-xs mb-4" style={{ color: "#7C8F7E" }}>Cita rápida: basta el nombre y el teléfono.</p>
      <Field label="Nombre de quien reserva"><input value={nombre} onChange={(e) => setNombre(e.target.value)} className={inputClass} autoFocus /></Field>
      <Field label="Teléfono (opcional)"><input value={telefono} onChange={(e) => setTelefono(e.target.value)} className={inputClass} /></Field>
      <Field label="Profesional (opcional)"><select value={profesionalId} onChange={(e) => setProfesionalId(e.target.value)} className={inputClass}><option value="">Sin asignar</option>{profesionales.map((p) => <option key={p.id} value={p.id}>{p.profesional || p.nombre}</option>)}</select></Field>
      <Field label="Motivo / tratamiento (opcional)"><select value={servicioId} onChange={(e) => elegirServicio(e.target.value)} className={inputClass}><option value="">Ninguno</option>{servicios.map((s) => <option key={s.id} value={s.id}>{s.nombre} — ${Number(s.precio).toFixed(2)}</option>)}</select></Field>
      <div className="grid grid-cols-3 gap-3"><Field label="Fecha"><input type="date" value={fecha} onChange={(e) => setFecha(e.target.value)} className={inputClass} /></Field><Field label="Hora"><input type="time" value={hora} onChange={(e) => setHora(e.target.value)} className={inputClass} /></Field><Field label="Duración"><select value={duracion} onChange={(e) => setDuracion(parseInt(e.target.value))} className={inputClass}>{[15, 20, 30, 40, 45, 50, 60, 75, 90, 120].map((d) => <option key={d} value={d}>{d} min</option>)}</select></Field></div>
      <p className="text-xs -mt-1 mb-2" style={{ color: "#7C9885" }}>Termina aprox. a las {_horaFin(hora, duracion)}</p>
      {cruce && <Aviso>Ese profesional ya tiene una cita a las {cruce.hora} ese día (puedes guardar igual).</Aviso>}
      {error && <p className="text-xs mb-3" style={{ color: "#B4694F" }}>{error}</p>}
      <Boton onClick={submit} disabled={guardando}>{guardando ? "Guardando…" : cita ? "Guardar cambios" : "Agendar cita"}</Boton>
    </Modal>
  );
}

// =====================================================================
//  Usuarios (admin) — crea usuarios con usuario+contraseña por local
// =====================================================================
const ROLES_ASIGNABLES = ["propietario", "asistente", "cosmetologa"];

function Usuarios({ api, profile, locales }) {
  const [usuarios, setUsuarios] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState("");
  const [modal, setModal] = useState(null); // null | "nuevo" | userObj

  const cargar = useCallback(async () => {
    setCargando(true); setError("");
    try { setUsuarios(await api.select("usuarios", "select=*,usuario_locales(local_id)&order=nombre.asc") || []); }
    catch (e) { setError("No se pudieron cargar los usuarios: " + e.message); }
    setCargando(false);
  }, [api]);
  useEffect(() => { cargar(); }, [cargar]);

  const nombreLocales = (u) => {
    if (u.rol === "admin") return "Todos";
    const ids = (u.usuario_locales || []).map((x) => x.local_id);
    return ids.map((id) => locales.find((l) => l.id === id)?.nombre ?? "—").join(", ") || "—";
  };

  const guardar = async (form, editandoId) => {
    try {
      let userId = editandoId;
      if (editandoId) {
        await api.update("usuarios", `id=eq.${editandoId}`, { username: form.username, password: form.password, nombre: form.nombre, rol: form.rol, profesional: form.rol === "cosmetologa" ? form.profesional : null });
      } else {
        const row = await api.insert("usuarios", { id: (crypto.randomUUID ? crypto.randomUUID() : String(Date.now())), username: form.username, password: form.password, nombre: form.nombre, rol: form.rol, activo: true, debe_cambiar_password: false, profesional: form.rol === "cosmetologa" ? form.profesional : null });
        userId = row.id;
      }
      await api.remove("usuario_locales", `usuario_id=eq.${userId}`);
      if (form.rol !== "admin" && form.locales.length) await api.insert("usuario_locales", form.locales.map((l) => ({ usuario_id: userId, local_id: l })));
      setModal(null); await cargar(); return {};
    } catch (e) { return { error: e.message }; }
  };
  const toggleActivo = async (u) => {
    if (u.id === profile.id) { setError("No puedes desactivar tu propio usuario."); return; }
    try { await api.update("usuarios", `id=eq.${u.id}`, { activo: !(u.activo !== false) }); cargar(); } catch (e) { setError(e.message); }
  };
  const eliminar = async (u) => {
    if (u.id === profile.id) { setError("No puedes eliminar tu propio usuario."); return; }
    if (!confirm(`¿Eliminar a ${u.nombre}?`)) return;
    try { await api.remove("usuario_locales", `usuario_id=eq.${u.id}`); await api.remove("usuarios", `id=eq.${u.id}`); cargar(); } catch (e) { setError(e.message); }
  };

  if (cargando) return <div><SectionTitle eyebrow="Acceso" title="Usuarios" /><Card className="p-8 text-center text-sm text-[#7C8F7E]">Cargando…</Card></div>;

  return (
    <div>
      <SectionTitle eyebrow="Acceso" title="Usuarios" action={<Boton onClick={() => setModal("nuevo")}><Plus size={16} />Nuevo usuario</Boton>} />
      {error && <Aviso>{error}</Aviso>}
      <p className="text-sm text-[#7C8F7E] mb-4">Crea usuarios con su usuario, contraseña, rol y local(es). El usuario entra eligiendo su local + usuario + contraseña.</p>
      <Card className="overflow-x-auto">
        <table className="w-full text-sm" style={{ minWidth: "720px" }}>
          <thead><tr className="text-left text-[#7C8F7E] text-xs uppercase tracking-wide border-b border-[#EFE9DA]" style={{ fontFamily: "'Sora', sans-serif" }}><th className="px-3 py-2.5 font-medium">Usuario</th><th className="px-3 py-2.5 font-medium">Nombre</th><th className="px-3 py-2.5 font-medium">Rol</th><th className="px-3 py-2.5 font-medium">Local</th><th className="px-3 py-2.5 font-medium">Estado</th><th className="px-3 py-2.5 font-medium text-right">Acciones</th></tr></thead>
          <tbody>
            {usuarios.map((u) => { const activo = u.activo !== false; return (
              <tr key={u.id} className="border-b border-[#F4EFE2]">
                <td className="px-3 py-2.5 font-mono text-xs text-[#2E2E2E]">{u.username}{u.id === profile.id && <span className="ml-1 text-[10px]" style={{ color: "#7C9885" }}>(tú)</span>}</td>
                <td className="px-3 py-2.5 text-[#2E2E2E]">{u.nombre}{u.profesional ? <span className="text-xs" style={{ color: "#A9B9AA" }}> · {u.profesional}</span> : null}</td>
                <td className="px-3 py-2.5"><span className="text-[10px] px-2 py-0.5 rounded-full" style={{ backgroundColor: u.rol === "admin" ? "#2E2E2E" : "#EEE9DC", color: u.rol === "admin" ? "#fff" : "#6A6152" }}>{ROLES[u.rol] ?? u.rol}</span></td>
                <td className="px-3 py-2.5 text-[#7C8F7E]">{nombreLocales(u)}</td>
                <td className="px-3 py-2.5">{activo ? <span className="text-xs" style={{ color: "#5D8065" }}>Activo</span> : <span className="text-xs" style={{ color: "#B4694F" }}>Inactivo</span>}</td>
                <td className="px-3 py-2.5 text-right whitespace-nowrap">
                  <button onClick={() => setModal(u)} className="text-xs mr-3" style={{ color: "#7C9885" }}>Editar</button>
                  {u.id !== profile.id && <button onClick={() => toggleActivo(u)} className="text-xs mr-3" style={{ color: "#7C8F7E" }}>{activo ? "Desactivar" : "Activar"}</button>}
                  {u.id !== profile.id && <button onClick={() => eliminar(u)} className="text-xs" style={{ color: "#B4694F" }}>Eliminar</button>}
                </td>
              </tr>
            ); })}
            {usuarios.length === 0 && <tr><td colSpan={6} className="px-3 py-6 text-center text-[#7C8F7E]">Sin usuarios.</td></tr>}
          </tbody>
        </table>
      </Card>
      {modal && <ModalUsuario usuario={modal === "nuevo" ? null : modal} usuarios={usuarios} locales={locales} onClose={() => setModal(null)} onGuardar={guardar} />}
    </div>
  );
}

function ModalUsuario({ usuario, usuarios, locales, onClose, onGuardar }) {
  const editando = !!usuario;
  const [username, setUsername] = useState(usuario?.username ?? "");
  const [password, setPassword] = useState(usuario?.password ?? "");
  const [nombre, setNombre] = useState(usuario?.nombre ?? "");
  const [rol, setRol] = useState(usuario?.rol ?? "asistente");
  const [profesional, setProfesional] = useState(usuario?.profesional ?? "");
  const [locSel, setLocSel] = useState((usuario?.usuario_locales || []).map((x) => x.local_id));
  const [error, setError] = useState(""); const [guardando, setGuardando] = useState(false);
  const rolesDisponibles = ["admin", ...ROLES_ASIGNABLES];
  const toggleLoc = (id) => setLocSel((a) => a.includes(id) ? a.filter((x) => x !== id) : [...a, id]);

  const submit = async () => {
    if (!username.trim() || !nombre.trim() || !password.trim()) { setError("Usuario, nombre y contraseña son obligatorios."); return; }
    const dup = usuarios.some((u) => (u.username || "").toLowerCase() === username.trim().toLowerCase() && u.id !== usuario?.id);
    if (dup) { setError("Ese usuario ya existe."); return; }
    if (rol !== "admin" && locSel.length === 0) { setError("Selecciona al menos un local."); return; }
    if (rol === "cosmetologa" && !profesional.trim()) { setError("Indica el nombre de la profesional."); return; }
    setError(""); setGuardando(true);
    const res = await onGuardar({ username: username.trim(), password: password.trim(), nombre: nombre.trim(), rol, profesional: profesional.trim(), locales: rol === "admin" ? [] : locSel }, usuario?.id);
    setGuardando(false); if (res?.error) setError(res.error);
  };

  return (
    <Modal title={editando ? "Editar usuario" : "Nuevo usuario"} onClose={onClose}>
      <div className="grid grid-cols-2 gap-3">
        <Field label="Usuario"><input value={username} onChange={(e) => setUsername(e.target.value)} className={inputClass} placeholder="ej. maria" autoFocus /></Field>
        <Field label="Contraseña"><input value={password} onChange={(e) => setPassword(e.target.value)} className={inputClass} placeholder="••••••" /></Field>
      </div>
      <Field label="Nombre de la persona"><input value={nombre} onChange={(e) => setNombre(e.target.value)} className={inputClass} placeholder="ej. María Pérez" /></Field>
      <Field label="Rol"><select value={rol} onChange={(e) => setRol(e.target.value)} className={inputClass}>{rolesDisponibles.map((r) => <option key={r} value={r}>{ROLES[r]}</option>)}</select></Field>
      {rol === "admin" ? (
        <p className="text-xs mb-4 px-3 py-2 rounded-lg" style={{ backgroundColor: "#FBF9F3", border: "1px solid #E7E1D2", color: "#7C8F7E" }}>El Administrador tiene acceso a todos los locales.</p>
      ) : (
        <div className="mb-4">
          <span className="block text-[13px] text-[#5E6E5F] mb-1.5" style={{ fontFamily: "'Sora', sans-serif" }}>Local(es)</span>
          <div className="flex flex-wrap gap-2">
            {locales.map((l) => { const sel = locSel.includes(l.id); return <button key={l.id} type="button" onClick={() => toggleLoc(l.id)} className="text-xs px-3 py-1.5 rounded-full border" style={sel ? { backgroundColor: "#7C9885", color: "#fff", borderColor: "#7C9885" } : { backgroundColor: "#fff", color: "#5E6E5F", borderColor: "#DDD6C2" }}>{sel && <Check size={12} className="inline mr-1" />}{l.nombre}</button>; })}
          </div>
        </div>
      )}
      {rol === "cosmetologa" && <Field label="Profesional vinculada"><input value={profesional} onChange={(e) => setProfesional(e.target.value)} className={inputClass} placeholder="ej. Grace" /></Field>}
      {error && <Aviso>{error}</Aviso>}
      <Boton onClick={submit} disabled={guardando}>{guardando ? "Guardando…" : editando ? "Guardar cambios" : "Crear usuario"}</Boton>
    </Modal>
  );
}
